import{_ as l,a0 as s,w as i,s as h,I as o,x as n,a1 as r,A as a,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"AI 内容审核最早的大规模落地，9 年前 Pornhub 就干了 | LCTT x X-CMD","titleTemplate":false,"description":"2017 年 10 月，Pornhub 上线 CV 模型识别 10000+ 表演者、每天扫描 5 万段视频。比 OpenAI CLIP、Meta SEER 都早，是 AI 内容理解最早的大规模工业实践之一。9 年后重看，这是 RLHF + CV 内容审核范式的雏形。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"AI 内容审核最早的大规模落地，9 年前 Pornhub 就干了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2017 年 10 月，Pornhub 上线 CV 模型识别 10000+ 表演者、每天扫描 5 万段视频。比 OpenAI CLIP、Meta SEER 都早，是 AI 内容理解最早的大规模工业实践之一。9 年后重看，这是 RLHF + CV 内容审核范式的雏形。"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171010 Pornhub launches new AI to watch and tag porn so humans dont have to.digest","title":"AI 内容审核最早的大规模落地，9 年前 Pornhub 就干了","tag":"201710","desc":"2017 年 10 月，Pornhub 上线 CV 模型识别 10000+ 表演者、每天扫描 5 万段视频。比 OpenAI CLIP、Meta SEER 都早，是 AI 内容理解最早的大规模工业实践之一。9 年后重看，这是 RLHF + CV 内容审核范式的雏形。"},"relativePath":"201710/20171010 Pornhub launches new AI to watch and tag porn so humans dont have to.digest.md","filePath":"[post].md"}'),p={name:"201710/20171010 Pornhub launches new AI to watch and tag porn so humans dont have to.digest.md"};function I(d,t,A,b,P,g){const e=s("Link");return i(),h("div",null,[t[13]||(t[13]=o("h1",{id:"ai-内容审核最早的大规模落地-9-年前-pornhub-就干了",tabindex:"-1"},[n("AI 内容审核最早的大规模落地，9 年前 Pornhub 就干了 "),o("a",{class:"header-anchor",href:"#ai-内容审核最早的大规模落地-9-年前-pornhub-就干了","aria-label":"Permalink to “AI 内容审核最早的大规模落地，9 年前 Pornhub 就干了”"},"​")],-1)),o("blockquote",null,[o("p",null,[t[1]||(t[1]=n("老文新评 #038 · ",-1)),r(e,{href:"https://thenextweb.com/artificial-intelligence/2017/10/11/pornhub-ai-watch-tag/",rel:"nofollow noopener"},{default:a(()=>[...t[0]||(t[0]=[n("thenextweb.com",-1)])]),_:1}),t[2]||(t[2]=n(" · 2017-10-10",-1))])]),t[14]||(t[14]=u('<p>2017 年 10 月，Pornhub 上线了一套 CV 模型，能识别 10000+ 表演者、每天扫描 5 万段视频——这是 AI 内容理解最早的大规模工业实践，比 OpenAI CLIP 还早半年。那时候 ImageNet 时代刚结束，深度学习在人脸识别上接近人类水平，但「工业化地用 CV 跑全量视频」还没成熟样本。Pornhub 是当时少数把模型推到日均 50 万级别处理量的玩家。</p><h2 id="文章讲了啥" tabindex="-1">文章讲了啥 <a class="header-anchor" href="#文章讲了啥" aria-label="Permalink to “文章讲了啥”">​</a></h2><p>Pornhub 副总裁 Corey Price 在 2017 年 10 月宣布，公司部署了一套计算机视觉模型：训练样本是数千段视频和表演者正片照，输出是演员名字 + 内容分类（户外 / 金发等）。模型每天扫描 5 万段新增视频，1 年内要编目全站 500 万视频。</p><p>运营上有个聪明设计：用户对 AI 给的标签可以投支持 / 反对票，反馈回流进模型训练。Price 把它包装成&quot;解放每日阅片无数的视频审核员&quot;的故事——用 AI 替代人工是核心卖点。</p><h2 id="_9-年后重读" tabindex="-1">9 年后重读 <a class="header-anchor" href="#_9-年后重读" aria-label="Permalink to “9 年后重读”">​</a></h2><p>Pornhub 2017 年这套系统的几个组件，今天看都属于&quot;提前用对了模式&quot;。</p><ul><li><strong>大规模 CV 落地</strong>：2017 年 ImageNet 时代刚结束，深度学习在人脸识别上接近人类水平，但&quot;工业化地用 CV 跑全量视频&quot;还没成熟样本。Pornhub 是当时少数把模型推到日均 50 万级别处理量的玩家。后来 OpenAI 用 CLIP 做多模态理解、Meta 用 SEER 做自监督、Google 用 Gemini 做视频理解——它们都用的是同一套范式，只不过 Pornhub 9 年前就在跑。</li><li><strong>用户反馈闭环</strong>：让用户对标签投支持 / 反对票，2017 年这是&quot;土法上马&quot;。但这套机制本质就是 RLHF 的早期形态——人类反馈 → 模型迭代。今天所有主流大模型公司都在做同一件事，只不过 Pornhub 当时让&quot;打飞机的人&quot;贡献了训练数据。</li><li><strong>替代人工的承诺</strong>：文章把 AI 上线包装成&quot;让阅片审核员终于解放&quot;。9 年后看这话有点讽刺——审核员没被完全解放，但工作量大幅减少；同时引出新问题：AI 误判、偏见、漏报、对抗样本。Pornhub 当年没预料到这些问题，今天所有内容平台都在处理。</li></ul><p>更要紧的是，2017 年的 Pornhub 没有&quot;AI Agent&quot;概念——它只是&quot;CV 分类器 + 人工反馈&quot;。但 2026 年回头看，这正是 AI Agent 范式的雏形：感知（CV 抽取特征）→ 决策（标签分类）→ 行动（写入数据库）→ 反馈（用户投票再训练）。这个流水线今天所有 AI Agent 平台都还在用。</p><h2 id="把-ai-当卖点-vs-把-ai-当工具" tabindex="-1">把 AI 当卖点 vs 把 AI 当工具 <a class="header-anchor" href="#把-ai-当卖点-vs-把-ai-当工具" aria-label="Permalink to “把 AI 当卖点 vs 把 AI 当工具”">​</a></h2><p>文章里有个细节值得拎出来：Pornhub 把 AI 包装成&quot;用户也参与贡献&quot;的协作故事——你点支持 / 反对票，就是在帮 AI 变聪明。</p><p>这跟 9 年后某些 AI 公司的&quot;民主化&quot;叙事几乎一模一样。区别是：Pornhub 当年的反馈是真的回流进了模型，2026 年某些大模型公司收集的&quot;用户反馈&quot;大部分进了数据仓库没回训练管道。</p><p>更深一层：&quot;让用户参与 AI 训练&quot;是个有真实价值的设计，但也是个有真实代价的设计。Pornhub 当年收集的用户反馈不可避免带偏见——某些品类的标签被反复支持、某些则被反复反对，模型被慢慢推向一个特定&quot;审美&quot;的分布。这种&quot;用户投票决定 AI 价值取向&quot;的设计，今天做内容审核的人应该警惕——用户觉得对的，未必是平台合规想要的。</p><p>AI 内容审核最大的难题不是技术，是&quot;训练分布和合规要求之间的鸿沟&quot;。Pornhub 9 年前没遇到这个问题，是因为成人网站当时基本没有&quot;合规&quot;概念——只有 SEO。今天所有大型内容平台都面对这个问题：用户投反对票的内容，往往是法律要求保留的；用户投支持票的内容，往往是法律要求删除的。</p><p>这条 9 年前的新闻真正的价值，是它展示了&quot;AI 内容审核&quot;这条赛道的起点有多低——一家成人网站、单功能模型、几千张训练图、几万段视频每天。再过 9 年，这条赛道变成了几百亿美元的产业、几百万小时的训练数据、几千个模型 SKU。起点从来不是问题，跑完赛程才是问题。</p><hr><p><strong>出处</strong></p>',16)),o("ul",null,[o("li",null,[t[4]||(t[4]=o("strong",null,"原文",-1)),t[5]||(t[5]=n("（ARR 风险）：",-1)),r(e,{href:"https://thenextweb.com/artificial-intelligence/2017/10/11/pornhub-ai-watch-tag/",rel:"nofollow noopener"},{default:a(()=>[...t[3]||(t[3]=[n("thenextweb.com",-1)])]),_:1})]),o("li",null,[t[7]||(t[7]=o("strong",null,"LCTT 译稿源档",-1)),t[8]||(t[8]=n("：",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[n("github.com/LCTT/TranslateProject",-1)])]),_:1})]),o("li",null,[t[10]||(t[10]=o("strong",null,"原译",-1)),t[11]||(t[11]=n("：",-1)),r(e,{href:"https://lctt.x-cmd.com/201710/20171010%20Pornhub%20launches%20new%20AI%20to%20watch%20and%20tag%20porn%20so%20humans%20dont%20have%20to/"},{default:a(()=>[...t[9]||(t[9]=[n("linux.cn",-1)])]),_:1})]),t[12]||(t[12]=o("li",null,[o("strong",null,"发布"),n("：2017-10-10")],-1))]),t[15]||(t[15]=u('<hr><h2 id="这些观点今天还成立吗" tabindex="-1">这些观点今天还成立吗？ <a class="header-anchor" href="#这些观点今天还成立吗" aria-label="Permalink to “这些观点今天还成立吗？”">​</a></h2><ul><li>✅ <strong>CV 识别表演者是工业级能力</strong> —— 现在 CLIP、VLM、Video-LLaVA 都已超越，但 Pornhub 是先驱</li><li>✅ <strong>用户反馈反哺模型</strong> —— RLHF / VLM 主流训练范式，2017 年 Pornhub 的&quot;投票&quot;模式本质就是早期 RLHF</li><li>⚠️ <strong>AI 解放人工审核员</strong> —— 部分对，但引出新问题（AI 偏见、漏判、对抗样本）</li><li>⚠️ <strong>每天 5 万视频是大数字</strong> —— 现在的 AI 一天能扫 500 万+；但 Pornhub 当年是这个数量级的先行者</li><li>⚠️ <strong>1 年内索引 500 万视频</strong> —— 2026 年的多模态模型 1 天就能完成同等工作，但&quot;工业化跑通&quot;这条 Pornhub 先做到了</li></ul>',3))])}const T=l(p,[["render",I]]);export{C as __pageData,T as default};
